# Patch each Individual node's dossier note with attack path summary
import sys, os, json
sys.path.insert(0, '/data/scripts')
import flowsint_client as fc

_env_sketch = os.environ.get('FLOWSINT_SKETCH_ID', '')
results = []
for item in _items:
    d = item.get('json', {})
    ind_id = d.get('ind_id', '')
    # The cloud-exposure item carries no ind_id -- it is about assets, not a
    # person -- so it MUST be handled before the guard below, which drops any
    # such item silently. That is how a whole feature ships computing a number
    # nothing persists.
    if d.get('kind') == 'cloud_exposure':
        for w in (d.get('cloud_writes') or []):
            cid = w.get('id')
            if not cid:
                continue
            try:
                # nodeProperties.-prefixed, or edit_node writes to the node's top
                # level where get_nodes_by_type and every panel query never look,
                # and all three layers still report success.
                fc.edit_node(cid, {
                    'nodeProperties.cloud_attack_bonus': w.get('bonus', 0),
                    'nodeProperties.cloud_attack_basis': w.get('attrib', 'unknown'),
                    'nodeProperties.cloud_attack_summary': json.dumps(w),
                }, sketch_id=(d.get('sketch_id') or _env_sketch))
            except Exception as e:
                d.setdefault('cloud_write_errors', []).append(str(e)[:200])
        results.append({'json': d})
        continue
    if not ind_id:
        continue
    try:
        fc.edit_node(ind_id, {
            'nodeProperties.attack_summary': json.dumps(d.get('attack_summary', {})),
            'nodeProperties.attack_score':   d.get('max_score', 0),
            'nodeProperties.is_high_value':  d.get('is_high_value', False),
        }, sketch_id=(d.get('sketch_id') or _env_sketch))
    except Exception as e:
        d['update_error'] = str(e)
    results.append({'json': d})
return results
